import os,json,subprocess,stat,time
from pathlib import Path
root=Path('/srv/projects')
def call(a,t=65):
 try:
  x=subprocess.run(a,capture_output=True,text=True,timeout=t)
  return (x.returncode,x.stdout.strip()[-5000:])
 except Exception:return(-9,'')
def du_top(p,depth=1):
 rc,out=call(['/usr/bin/du','-k','--max-depth='+str(depth),'--one-file-system',str(p)],100)
 items=[]
 if rc==0:
  for line in out.splitlines():
   s=line.split('\t',1)
   if len(s)==2 and s[0].isdigit() and s[1]!=str(p):
    items.append({'path':str(Path(s[1]).relative_to(root)),'MB':round(int(s[0])*1024/1e6,1)})
 return sorted(items,key=lambda x:-x['MB'])[:45]
def filelist(p):
 return [{'name':x.name,'link':os.readlink(x) if x.is_symlink() else None,'directory':x.is_dir(),'bytes':x.stat().st_size if x.is_file() and not x.is_symlink() else None} for x in sorted(p.iterdir(),key=lambda y:y.name)[:36]] if p.is_dir() else []
r={'audit':'vps-large-residue-ownership-and-live-release','time':time.strftime('%FT%TZ',time.gmtime()),'mode':'read-only'}
r['pink_tests']=du_top(root/'pink-iptv/tests',2)
r['pink_tests_root']=filelist(root/'pink-iptv/tests')
r['fadego_releases']=du_top(root/'fadego/releases',1)
r['fadego_symlinks']={x:os.readlink(root/'fadego'/x) if (root/'fadego'/x).is_symlink() else None for x in ('current','www')}
r['fadego_local']=du_top(root/'fadego/.local',2)
r['hopper']={'children':filelist(root/'hopper'), 'bin':filelist(root/'hopper/bin'), 'lib':filelist(root/'hopper/lib')}
r['orphan_codex_alias']={'target':os.readlink(root/'codex-agent') if (root/'codex-agent').is_symlink() else None}
r['git_provenance']={}
for name in ('pink-iptv','iptvpn-bot','lowcost-europa','telegram-robot-leads','fadego','Codex','skill-universal','VPS'):
 p=root/name
 info={'git_dir_exists':(p/'.git').exists(),'current_link':os.readlink(p/'current') if (p/'current').is_symlink() else None}
 if (p/'.git').is_dir():
  for k,args in [('sha',['rev-parse','HEAD']),('branch',['branch','--show-current'])]:
   code,text=call(['/usr/bin/git','-c','safe.directory='+str(p),'-C',str(p),*args],10)
   info[k]=text[:75] if code==0 else None
 for f in ('.verified-source-commit','CURRENT_SHA','CURRENT_SOURCE_SHA','.source-commit','REVISION'):
  if (p/f).is_file():
   b=(p/f).read_text(errors='ignore')
   if len(b)<160 and all(c in '0123456789abcdefABCDEF\n \t' for c in b):info[f]=b.strip()
 r['git_provenance'][name]=info
rc,out=call(['/usr/bin/apt-get','-s','autoremove','--purge'],30)
r['apt_autoremove_sim']={'exit':rc,'changes':[s.strip() for s in out.splitlines() if s.startswith(('Remv ','Purg '))][:80]}
rc,out=call(['/usr/bin/dpkg-query','-W'],20)
r['android_apt']=[line for line in out.splitlines() if any(z in line.lower() for z in ('android','adb','apktool','aapt','zipalign','gradle','qemu-system'))][:90]
print(json.dumps(r,ensure_ascii=True,sort_keys=True))
